referenceSolutions.javascript:
export function searchA2dMatrix(matrix            , target        )          {
if(!matrix.length||!matrix[0].length)return false;const w=matrix[0].length;let l=0,r=matrix.length*w-1;while(l<=r){const m=(l+r)>>1,x=matrix[Math.floor(m/w)][m%w];if(x===target)return true;if(x<target)l=m+1;else r=m-1;}return false;
}

